#!/usr/bin/env node
/**
 * Verify LLM-"recalled" abstracts (and authors) against real bibliographic sources.
 *
 * Targets every work with raw_data.abstract_source in ('gemini_recall','qwen_recall')
 * — i.e. abstracts that were GENERATED by an LLM from training-data recall, not
 * retrieved from a source (see 2026-07-15 Sebastian-feedback incident: fabricated
 * abstract on 10.1016/j.jdeveco.2014.01.003). Also checks recalled authors
 * (raw_data.author_source in the same set).
 *
 * REPORT mode (default): fetches the real abstract from OpenAlex (batch, 50 DOIs
 * per request) with a Semantic Scholar batch fallback, computes token-set
 * similarity vs the stored text, and writes
 *   reports/recalled-abstracts-verification.jsonl   (one row per work)
 *   reports/recalled-abstracts-verification-summary.json
 * No DB writes.
 *
 * APPLY mode (--apply, reads the JSONL from a prior report run):
 *   - real abstract FOUND  → replace stored abstract with the retrieved text,
 *     raw_data.abstract_source = 'openalex'|'s2', abstract_verified_at stamped.
 *     If the recalled text was divergent (< SIM_CLOSE) → also raw_data.sms_stale
 *     + embedding_stale = true (SMS + embedding were computed off fabricated text).
 *   - real abstract NOT FOUND → abstract = null (quarantine),
 *     raw_data.abstract_source = 'recall_quarantined' (+ recall provenance kept in
 *     abstract_recall_original_source), sms_stale + embedding_stale = true.
 *   - recalled authors + OpenAlex authors found → replace works.authors,
 *     raw_data.author_source = 'openalex'.
 * Only rows carrying the recall flags are ever touched (golden rule: never
 * clobber curated/retrieved data).
 *
 * Usage:
 *   node --env-file=.env scripts/verify-recalled-abstracts.mjs            # report
 *   node --env-file=.env scripts/verify-recalled-abstracts.mjs --limit 50 # sample
 *   node --env-file=.env scripts/verify-recalled-abstracts.mjs --apply    # apply from report
 */
import { createClient } from '@supabase/supabase-js';
import { config } from 'dotenv';
import fs from 'fs';
config();

const args = process.argv.slice(2);
const flag = (name, fallback) => {
  const i = args.indexOf(name);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const APPLY = args.includes('--apply');
const LIMIT = parseInt(flag('--limit', '0')) || Infinity;
const MAILTO = process.env.OPENALEX_MAILTO || 'jessica@nextminder.com';

const JSONL_PATH = 'reports/recalled-abstracts-verification.jsonl';
const SUMMARY_PATH = 'reports/recalled-abstracts-verification-summary.json';

// Similarity thresholds (token-set Jaccard on the normalized texts)
const SIM_VERBATIM = 0.85;
const SIM_CLOSE = 0.6;

const sb = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY,
  { auth: { persistSession: false } }
);

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

function normalizeText(s) {
  return (s || '')
    .toLowerCase()
    .normalize('NFKD').replace(/[̀-ͯ]/g, '')
    .replace(/<[^>]+>/g, ' ')      // JATS/HTML tags in Crossref-style abstracts
    .replace(/&[a-z]+;/g, ' ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenSet(s) {
  return new Set(normalizeText(s).split(' ').filter(w => w.length >= 3));
}

function similarity(a, b) {
  const A = tokenSet(a), B = tokenSet(b);
  if (!A.size || !B.size) return { jaccard: 0, containment: 0 };
  let inter = 0;
  for (const w of A) if (B.has(w)) inter++;
  return {
    jaccard: inter / (A.size + B.size - inter),
    containment: inter / Math.min(A.size, B.size),
  };
}

function surname(name) {
  if (!name) return '';
  const n = String(name).trim();
  // "Keefer, Philip" → Keefer ; "Philip Keefer" → Keefer
  if (n.includes(',')) return n.split(',')[0].trim().toLowerCase();
  const parts = n.split(/\s+/);
  return (parts[parts.length - 1] || '').toLowerCase();
}

function invertAbstract(inv) {
  if (!inv) return null;
  const arr = [];
  for (const [word, positions] of Object.entries(inv)) {
    for (const p of positions) arr[p] = word;
  }
  const text = arr.join(' ').trim();
  return text.length > 40 ? text : null;
}

async function loadTargets() {
  const rows = [];
  let from = 0;
  for (;;) {
    const { data, error } = await sb.from('works')
      .select('id, title, year, canonical_doi, abstract, authors, raw_data')
      .filter('raw_data->>abstract_source', 'in', '("gemini_recall","qwen_recall")')
      .order('id')
      .range(from, from + 999);
    if (error) throw new Error('loadTargets: ' + error.message);
    if (!data?.length) break;
    rows.push(...data);
    if (data.length < 1000 || rows.length >= LIMIT) break;
    from += 1000;
    process.stdout.write(`\r  loaded ${rows.length}...`);
  }
  // Also pick up author-only recall rows (recalled authors but real abstract)
  let from2 = 0;
  for (;;) {
    const { data, error } = await sb.from('works')
      .select('id, title, year, canonical_doi, abstract, authors, raw_data')
      .filter('raw_data->>author_source', 'in', '("gemini_recall","qwen_recall")')
      .order('id')
      .range(from2, from2 + 999);
    if (error) throw new Error('loadTargets(authors): ' + error.message);
    if (!data?.length) break;
    for (const r of data) if (!rows.some(x => x.id === r.id)) rows.push(r);
    if (data.length < 1000) break;
    from2 += 1000;
  }
  return rows.slice(0, LIMIT === Infinity ? rows.length : LIMIT);
}

async function fetchOpenAlexBatch(dois) {
  const filter = 'doi:' + dois.join('|');
  const url = `https://api.openalex.org/works?filter=${encodeURIComponent(filter)}&per-page=${dois.length}&select=doi,title,abstract_inverted_index,authorships&mailto=${encodeURIComponent(MAILTO)}`;
  for (let attempt = 0; attempt < 4; attempt++) {
    try {
      const res = await fetch(url);
      if (res.status === 429 || res.status >= 500) { await sleep(2000 * (attempt + 1)); continue; }
      if (!res.ok) return new Map();
      const json = await res.json();
      const map = new Map();
      for (const w of json.results || []) {
        const doi = (w.doi || '').replace(/^https?:\/\/doi\.org\//i, '').toLowerCase();
        map.set(doi, {
          abstract: invertAbstract(w.abstract_inverted_index),
          authors: (w.authorships || []).map(a => a.author?.display_name).filter(Boolean),
        });
      }
      return map;
    } catch { await sleep(2000 * (attempt + 1)); }
  }
  return new Map();
}

async function fetchS2Batch(dois) {
  const url = 'https://api.semanticscholar.org/graph/v1/paper/batch?fields=abstract,externalIds';
  for (let attempt = 0; attempt < 5; attempt++) {
    try {
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ ids: dois.map(d => 'DOI:' + d) }),
      });
      if (res.status === 429 || res.status >= 500) { await sleep(3000 * (attempt + 1)); continue; }
      if (!res.ok) return new Map();
      const json = await res.json();
      const map = new Map();
      json.forEach((p, i) => {
        if (p && p.abstract && p.abstract.length > 40) map.set(dois[i].toLowerCase(), { abstract: p.abstract });
      });
      return map;
    } catch { await sleep(3000 * (attempt + 1)); }
  }
  return new Map();
}

function bucketFor(sim) {
  if (sim.jaccard >= SIM_VERBATIM) return 'verbatim';
  if (sim.jaccard >= SIM_CLOSE || sim.containment >= 0.8) return 'close';
  return 'divergent';
}

async function report() {
  console.log('=== Verify recalled abstracts (REPORT mode) ===');
  const targets = await loadTargets();
  const withAbs = targets.filter(t => t.abstract);
  console.log(`\nTargets: ${targets.length} flagged rows (${withAbs.length} with a stored recalled abstract)`);

  fs.mkdirSync('reports', { recursive: true });
  const out = fs.createWriteStream(JSONL_PATH);
  const counts = { verbatim: 0, close: 0, divergent: 0, not_found: 0, no_doi: 0, author_rows: 0, authors_fixable: 0 };

  const withDoi = targets.filter(t => t.canonical_doi);
  const noDoi = targets.filter(t => !t.canonical_doi);
  for (const t of noDoi) {
    counts.no_doi++;
    out.write(JSON.stringify({ id: t.id, doi: null, outcome: 'no_doi' }) + '\n');
  }

  let processed = 0;
  for (let i = 0; i < withDoi.length; i += 50) {
    const batch = withDoi.slice(i, i + 50);
    const dois = batch.map(t => t.canonical_doi.toLowerCase());
    const oa = await fetchOpenAlexBatch(dois);

    // S2 fallback only for rows OpenAlex had no abstract for
    const missing = batch.filter(t => !oa.get(t.canonical_doi.toLowerCase())?.abstract);
    const s2 = missing.length ? await fetchS2Batch(missing.map(t => t.canonical_doi.toLowerCase())) : new Map();

    for (const t of batch) {
      const doi = t.canonical_doi.toLowerCase();
      const oaHit = oa.get(doi);
      const realAbs = oaHit?.abstract || s2.get(doi)?.abstract || null;
      const source = oaHit?.abstract ? 'openalex' : (s2.get(doi)?.abstract ? 's2' : null);

      const isAbsRecalled = ['gemini_recall', 'qwen_recall'].includes(t.raw_data?.abstract_source) && !!t.abstract;
      const isAuthRecalled = ['gemini_recall', 'qwen_recall'].includes(t.raw_data?.author_source);
      if (isAuthRecalled) counts.author_rows++;

      const row = {
        id: t.id, doi, title: (t.title || '').slice(0, 120),
        recall_source: t.raw_data?.abstract_source || null,
        author_recall: isAuthRecalled ? t.raw_data?.author_source : null,
      };

      if (isAbsRecalled) {
        if (realAbs) {
          const sim = similarity(t.abstract, realAbs);
          row.outcome = bucketFor(sim);
          row.jaccard = +sim.jaccard.toFixed(3);
          row.containment = +sim.containment.toFixed(3);
          row.real_abstract = realAbs;
          row.real_abstract_source = source;
          counts[row.outcome]++;
        } else {
          row.outcome = 'not_found';
          counts.not_found++;
        }
      } else {
        row.outcome = 'author_only';
      }

      if (isAuthRecalled && oaHit?.authors?.length) {
        row.real_authors = oaHit.authors;
        const storedSurnames = new Set((t.authors || []).map(surname));
        const realSurnames = new Set(oaHit.authors.map(surname));
        let overlap = 0;
        for (const s of storedSurnames) if (realSurnames.has(s)) overlap++;
        row.author_surname_overlap = storedSurnames.size ? +(overlap / Math.max(storedSurnames.size, realSurnames.size)).toFixed(2) : 0;
        counts.authors_fixable++;
      }

      out.write(JSON.stringify(row) + '\n');
    }

    processed += batch.length;
    process.stdout.write(`\r  ${processed}/${withDoi.length} | verbatim ${counts.verbatim} | close ${counts.close} | divergent ${counts.divergent} | not_found ${counts.not_found}`);
    await sleep(150); // OpenAlex polite pool
  }

  out.end();
  const summary = {
    generated_at: new Date().toISOString(),
    targets: targets.length,
    with_recalled_abstract: withAbs.length,
    thresholds: { verbatim: SIM_VERBATIM, close: SIM_CLOSE },
    counts,
  };
  fs.writeFileSync(SUMMARY_PATH, JSON.stringify(summary, null, 2));
  console.log('\n\nSummary:', JSON.stringify(summary, null, 2));
  console.log(`\nDetail: ${JSONL_PATH}`);
  console.log('Next: re-run with --apply to remediate.');
}

async function apply() {
  console.log('=== Verify recalled abstracts (APPLY mode) ===');
  if (!fs.existsSync(JSONL_PATH)) { console.error(`No report at ${JSONL_PATH} — run report mode first.`); process.exit(1); }
  const rows = fs.readFileSync(JSONL_PATH, 'utf8').split('\n').filter(Boolean).map(l => JSON.parse(l));
  console.log(`Report rows: ${rows.length}`);

  const stamp = new Date().toISOString();
  let replaced = 0, quarantined = 0, authorsFixed = 0, skipped = 0, errors = 0;

  for (const r of rows) {
    try {
      // Re-read the live row: only touch rows STILL carrying recall flags.
      const { data: live, error: readErr } = await sb.from('works')
        .select('id, abstract, authors, raw_data').eq('id', r.id).single();
      if (readErr || !live) { errors++; continue; }
      const raw = { ...(live.raw_data || {}) };
      const absRecalled = ['gemini_recall', 'qwen_recall'].includes(raw.abstract_source) && !!live.abstract;
      const authRecalled = ['gemini_recall', 'qwen_recall'].includes(raw.author_source);
      const patch = {};

      if (absRecalled && ['verbatim', 'close', 'divergent'].includes(r.outcome) && r.real_abstract) {
        patch.abstract = r.real_abstract;
        raw.abstract_source = r.real_abstract_source;           // 'openalex' | 's2'
        raw.abstract_recall_original_source = r.recall_source;  // provenance trail
        raw.abstract_verified_at = stamp;
        raw.abstract_recall_similarity = r.jaccard;
        delete raw.abstract_model;
        if (r.outcome === 'divergent') { raw.sms_stale = true; raw.embedding_stale = true; }
        replaced++;
      } else if (absRecalled && (r.outcome === 'not_found' || r.outcome === 'no_doi')) {
        patch.abstract = null;
        raw.abstract_recall_original_source = raw.abstract_source;
        raw.abstract_source = 'recall_quarantined';
        raw.abstract_quarantined_at = stamp;
        raw.sms_stale = true;
        raw.embedding_stale = true;
        quarantined++;
      }

      if (authRecalled && Array.isArray(r.real_authors) && r.real_authors.length) {
        patch.authors = r.real_authors;
        raw.author_recall_original_source = raw.author_source;
        raw.author_source = 'openalex';
        raw.authors_verified_at = stamp;
        authorsFixed++;
      }

      if (Object.keys(patch).length === 0) { skipped++; continue; }
      patch.raw_data = raw;
      const { error } = await sb.from('works').update(patch).eq('id', r.id);
      if (error) errors++;
    } catch { errors++; }
    if ((replaced + quarantined + skipped + errors) % 200 === 0) {
      process.stdout.write(`\r  replaced ${replaced} | quarantined ${quarantined} | authors fixed ${authorsFixed} | skipped ${skipped} | errors ${errors}`);
    }
  }

  const summary = { applied_at: stamp, replaced, quarantined, authorsFixed, skipped, errors };
  console.log('\n\nDone:', JSON.stringify(summary, null, 2));
  fs.writeFileSync('reports/recalled-abstracts-apply-summary.json', JSON.stringify(summary, null, 2));
  console.log('NOTE: quarantined/divergent rows are marked raw_data.sms_stale + embedding_stale — run the SMS reclassify and re-embed passes (off-peak) to clear them.');
}

(APPLY ? apply() : report()).catch(e => { console.error('Fatal:', e); process.exit(1); });
